mapper.select:
SELECT im.ingredient_id,im.base_unit FROM the_full_order.tb_account_ingredient_master im
WHERE im.account_id=#{account_id} AND im.ingredient_id=#{source_ingredient_id}
FOR UPDATE

SELECT po.*,s.supplier_code,s.supplier_name FROM the_full_order.tb_account_purchase_order po
JOIN the_full_order.tb_supplier s ON s.supplier_id=po.supplier_id
WHERE po.account_id=#{account_id} AND po.purchase_order_id=#{purchase_order_id}


SELECT po.*,s.supplier_code,s.supplier_name,
       (SELECT a.account_name FROM the_full.tb_account a WHERE a.account_id=po.account_id LIMIT 1) account_name,
       (SELECT ss.external_site_name FROM the_full_order.tb_supplier_account_site ss
         WHERE ss.account_id=po.account_id AND ss.supplier_id=po.supplier_id AND ss.external_site_code=po.sold_to
         ORDER BY ss.active_yn DESC LIMIT 1) site_name
  FROM the_full_order.tb_account_purchase_order po
JOIN the_full_order.tb_supplier s ON s.supplier_id=po.supplier_id WHERE po.account_id=#{account_id}
AND po.purchase_order_id=#{purchase_order_id}
AND po.created_at>=#{date_from}
AND po.created_at<DATE_ADD(#{date_to},INTERVAL 1 DAY)
AND po.status=#{status}
AND po.supplier_id=#{supplier_id}
ORDER BY po.created_at DESC,po.purchase_order_id DESC LIMIT #{limit} OFFSET #{offset}

SELECT i.*,po.account_id,po.supplier_id,po.sold_to,po.client_ord, NULLIF(i.source_ingredient_id,'') ingredient_id, COALESCE(ai.ingredient_name_std,ai.ingredient_name_raw) ingredient_name,ai.base_unit ingredient_base_unit, COALESCE(i.product_name_snapshot,p.product_name) product_name,p.base_qty product_base_qty,p.base_unit product_base_unit, p.alt_base_qty,p.alt_base_unit,ai.default_location_id,ss.supplier_account_site_id, CASE WHEN fp.favorite_product_id IS NULL THEN 'N' ELSE 'Y' ENDNULL favorite_yn FROM the_full_order.tb_account_purchase_order_item i JOIN the_full_order.tb_account_purchase_order po ON po.purchase_order_id=i.purchase_order_id JOIN the_full_order.tb_supplier_ingredient_product p ON p.supplier_product_id=i.supplier_product_id LEFT JOIN the_full_order.tb_account_ingredient_master ai ON ai.account_id=po.account_id AND ai.ingredient_id=i.source_ingredient_id LEFT JOIN the_full_order.tb_supplier_account_site ss ON ss.account_id=po.account_id AND ss.supplier_id=po.supplier_id AND ss.external_site_code=po.sold_to
LEFT JOIN the_full_order.tb_favorite_product fp ON fp.supplier_product_id=i.supplier_product_id AND fp.owner_type=#{favorite_owner_type} AND fp.owner_id=#{favorite_owner_id}
WHERE po.account_id=#{account_id} AND po.purchase_order_id=#{purchase_order_id} ORDER BY i.purchase_order_item_id FOR UPDATE

SELECT COUNT(*) FROM the_full_order.tb_goods_receipt_item i JOIN the_full_order.tb_goods_receipt r ON r.goods_receipt_id=i.goods_receipt_id
WHERE r.account_id=#{account_id} AND i.purchase_order_item_id=#{purchase_order_item_id}
  AND r.provider_receipt_key LIKE 'MANUAL|%' AND i.inventory_movement_id IS NOT NULL
